// Run history is built here, in the viewer's browser, from successive snapshots.
const US=new URLSearchParams(location.search).get('us')||'error404.ai';
const KEY='stage-watch-v1',MAX_SAMPLES=300,GONE_AFTER=2;
let store={runs:{},finished:[]};
try{const d=JSON.parse(localStorage.getItem(KEY)||'null');if(d&&d.runs)store=d}catch(e){}
const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(store))}catch(e){}};

function ingest(snap){
  const now=snap.at,seen=new Set();
  for(const r of snap.rows){
    seen.add(r.id);
    const run=store.runs[r.id]||(store.runs[r.id]={id:r.id,team:r.team,kind:r.kind,first_seen:now,samples:[],miss:0});
    Object.assign(run,{phase:r.phase,last_seen:now,miss:0});
    if(r.kind)run.kind=r.kind;
    if(r.secs!=null){
      Object.assign(run,{secs:r.secs,calls:r.calls,cost:r.cost});
      const l=run.samples[run.samples.length-1];
      if(!l||l[1]!==r.secs||l[2]!==r.calls||l[3]!==r.cost){run.samples.push([now,r.secs,r.calls,r.cost]);if(run.samples.length>MAX_SAMPLES)run.samples.shift()}
    }
  }
  for(const id of Object.keys(store.runs)){
    if(seen.has(id))continue;
    const run=store.runs[id];
    if(++run.miss>=GONE_AFTER){run.ended=run.last_seen;store.finished.unshift(run);delete store.runs[id];store.finished.length=Math.min(store.finished.length,200)}
  }
  persist();
  S={us:US,polled_at:now,running_total:snap.running_total,listed:snap.rows.length,
     runs:Object.values(store.runs),finished:store.finished,live:snap.live};
}

async function tick(){
  try{
    const r=await fetch('api/state',{cache:'no-store'});
    if(!r.ok)throw new Error(r.status);
    ingest(await r.json());render();
  }catch(e){$('dot').className='dot off';$('status').textContent='data source unreachable, retrying'}
}
tick();setInterval(tick,5000);setInterval(render,1000);

